import type { Contracts } from "@mainsail/contracts";

import { blockHeader, blockSerialized } from "./block.js";
import { lockProof, serializedLockProof } from "./lock-proof.js";

// PROPOSAL WITH LOCK PROOF

export const payload: Contracts.Crypto.ProposedPayload = {
	block: {
		serialized: blockSerialized,
	},
	lockProof,
};

export const payloadSerialized = "69" + serializedLockProof + blockSerialized; // 

export const proposalDataSerializableUnsigned: Contracts.Crypto.ProposalDataSerializableUnsigned = {
	payloadSerialized,
	round: 1,
	validRound: undefined,
	validatorIndex: 0,
};

// 
export const proposalSerializedUnsigned = "01000000000011030000" + payloadSerialized;

export const signature =
	"92c993a38d3b1fa1563820efbb54252086b764ac46a37dfda9b0dfc0eafb26be4891d890d86d477410063475373736b50f67c5191d8e0c3d4aaa773161fda1c0b1a844f9a987a550cc3cd422950820c90d63a698b532b03ba2894557311f66e7";

export const proposalDataSerializable: Contracts.Crypto.ProposalDataSerializable = {
	...proposalDataSerializableUnsigned,
	signature,
};

export const proposalSerialized = "01000000000011030000" + payloadSerialized + signature;

export const proposalData: Contracts.Crypto.ProposalData = {
	...proposalDataSerializable,
	blockHeader,
	lockProof,
};
